def is_valid_isbn10(s: str) -> bool:
    t = s.replace('-', '').replace(' ', '')
    if len(t) != 10:
        return False
    if not t[:9].isdigit():
        return False
    last = t[9]
    if not (last.isdigit() or last == 'X'):
        return False
    digits = [int(c) for c in t[:9]] + ([10] if last == 'X' else [int(last)])
    total = sum(d * w for d, w in zip(digits, range(10, 0, -1)))
    return total % 11 == 0

