from typing import List
import random

def quickselect(arr: List[int], k: int) -> int:
    """
    Returns the kth smallest element (1-indexed) using Quickselect.
    Partitions around a random pivot: elements < pivot go left, > pivot go right.
    Recurses only into the partition containing the kth element.
    Average O(n), worst O(n²).
    """
    if k < 1 or k > len(arr):
        raise ValueError("k out of bounds")

    def select(lo: int, hi: int, k_smallest: int) -> int:
        if lo == hi:
            return arr[lo]

        pivot_idx = random.randint(lo, hi)
        arr[pivot_idx], arr[hi] = arr[hi], arr[pivot_idx]

        # Partition
        store_idx = lo
        for i in range(lo, hi):
            if arr[i] < arr[hi]:
                arr[store_idx], arr[i] = arr[i], arr[store_idx]
                store_idx += 1
        arr[store_idx], arr[hi] = arr[hi], arr[store_idx]

        if k_smallest == store_idx:
            return arr[store_idx]
        elif k_smallest < store_idx:
            return select(lo, store_idx - 1, k_smallest)
        else:
            return select(store_idx + 1, hi, k_smallest)

    return select(0, len(arr) - 1, k - 1)

